import fs from "node:fs";
import path from "node:path";

const dist = path.join(process.cwd(), "dist");
if (!fs.existsSync(dist)) process.exit(0);

// Canonicalize both desktop and hamburger LINE sticker links generated by site-header.js.
const headerJs = path.join(dist, "site-header.js");
if (fs.existsSync(headerJs)) {
  let js = fs.readFileSync(headerJs, "utf8");
  js = js.replaceAll("'/#stickers'", "'/stickers/'");
  js = js.replaceAll('"/#stickers"', '"/stickers/"');
  fs.writeFileSync(headerJs, js);
}

function walk(dir) {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const full = path.join(dir, entry.name);
    return entry.isDirectory() ? walk(full) : [full];
  });
}

for (const file of walk(dist).filter((file) => file.endsWith(".html"))) {
  let html = fs.readFileSync(file, "utf8");

  // Any static header/hero LINE sticker link should use the collection page, not a home anchor.
  html = html.replaceAll('href="#stickers"', 'href="/stickers/"');
  html = html.replaceAll('href="/#stickers"', 'href="/stickers/"');

  // Sticker detail pages already render their own breadcrumb. Do not inject a second global breadcrumb.
  if (/(?:^|[\\/])stickers[\\/]\d+[\\/]index\.html$/.test(file)) {
    html = html.replace(/<script[^>]+src=["']\/site-breadcrumbs\.js(?:\?[^"']*)?["'][^>]*><\/script>/gi, "");
  }

  fs.writeFileSync(file, html);
}

console.log("Sticker navigation unified to /stickers/ and duplicate detail breadcrumbs disabled.");
